{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "After oral administration to rats, ACT001 reached brain concentrations (12,748.75 ± 4386.25 ng/mL) higher than plasma Cmax (6971.25 ± 1929.43 ng/mL), demonstrating direct CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "After bolus intravenous administration to mice, bufotalin brain concentrations at 30 min were significantly higher than blood concentrations (p < 0.05), indicating BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In guinea pigs, methylprednisolone blood-to-brain transport was slow (0.5–0.7 µL/min/g) and labeled impermeable, suggesting limited CNS access in that model.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predominantly direct in-vivo evidence across multiple compounds shows brain concentrations exceeding plasma or clear brain uptake after systemic administration; the single mixed low-rate transport record does not outweigh the consistent positive CNS-access evidence.",
  "evidence_gaps": [
    "Methylprednisolone evidence is mixed: low-rate blood-to-brain transfer in guinea pigs versus increased CSF penetration under P-gp inhibition; the relevance of P-gp modulation to the query is uncertain.",
    "Most direct CNS-access evidence comes from rodent studies; human evidence is limited to a steroid PET study."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

